INSERT INTO patient (patient_code,name,age,gender,label,clinical_data,biomarker,kidney_case_id,kidney_pool,dataset_version,provenance) SELECT patient_code,name,age,gender,label,clinical_data,biomarker,kidney_case_id,kidney_pool,dataset_version,provenance FROM seed_patient ON CONFLICT DO NOTHING;
INSERT INTO patient_image (patient_id,img_type,slice_index,file_path,description,image_metadata) SELECT p.id,s.img_type,s.slice_index,s.file_path,s.description,s.image_metadata FROM seed_image s JOIN patient p ON p.patient_code=s.patient_code ON CONFLICT DO NOTHING;
