-- Generated from project40_manifest.csv. Run after database/schema.sql.
BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE TEMP TABLE seed_patient ON COMMIT DROP AS SELECT patient_code,name,age,gender,label,clinical_data,biomarker,kidney_case_id,kidney_pool,dataset_version,provenance FROM patient WITH NO DATA;
CREATE TEMP TABLE seed_image ON COMMIT DROP AS SELECT p.patient_code,i.img_type,i.slice_index,i.file_path,i.description,i.image_metadata FROM patient_image i JOIN patient p ON p.id=i.patient_id WHERE p.dataset_version='kidney-diabetes-teaching40-v1' WITH NO DATA;
DO $verify$
BEGIN
    IF EXISTS ((SELECT patient_code,name,age,gender,label,clinical_data,biomarker,kidney_case_id,kidney_pool,dataset_version,provenance FROM seed_patient EXCEPT SELECT patient_code,name,age,gender,label,clinical_data,biomarker,kidney_case_id,kidney_pool,dataset_version,provenance FROM patient WHERE dataset_version='kidney-diabetes-teaching40-v1')
               UNION ALL (SELECT patient_code,name,age,gender,label,clinical_data,biomarker,kidney_case_id,kidney_pool,dataset_version,provenance FROM patient WHERE dataset_version='kidney-diabetes-teaching40-v1' EXCEPT SELECT patient_code,name,age,gender,label,clinical_data,biomarker,kidney_case_id,kidney_pool,dataset_version,provenance FROM seed_patient)) THEN
        RAISE EXCEPTION 'Patient seed conflicts with existing data; transaction rolled back.';
    END IF;
    IF EXISTS ((SELECT patient_code,img_type,slice_index,file_path,description,image_metadata FROM seed_image EXCEPT SELECT p.patient_code,i.img_type,i.slice_index,i.file_path,i.description,i.image_metadata FROM patient_image i JOIN patient p ON p.id=i.patient_id WHERE p.dataset_version='kidney-diabetes-teaching40-v1')
               UNION ALL (SELECT p.patient_code,i.img_type,i.slice_index,i.file_path,i.description,i.image_metadata FROM patient_image i JOIN patient p ON p.id=i.patient_id WHERE p.dataset_version='kidney-diabetes-teaching40-v1' EXCEPT SELECT patient_code,img_type,slice_index,file_path,description,image_metadata FROM seed_image)) THEN
        RAISE EXCEPTION 'Image seed conflicts with existing data; transaction rolled back.';
    END IF;
END;
$verify$;
COMMIT;
